import { LitElement, html, unsafeCSS } from "lit";
import { property } from "lit/decorators.js";
// These elements are rendered inside this component's shadow DOM (the
// tooltip and its trigger icon, shown when `tooltip` is set), so they must be
// registered whenever nys-label is used. Importing them here (intentional
// side effect) guarantees they always render.
import "@nysds/nys-tooltip";
import "@nysds/nys-icon";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-label.scss?inline";

let labelIdCounter = 0;

/**
 * **Internal component.** Renders form labels with description, required/optional flag, and tooltip.
 *
 * Used internally by form components (textinput, select, checkbox, etc.). Not intended for direct use.
 * Handles label association via `for`, displays asterisk for required fields, and integrates tooltips.
 *
 * @example Basic
 * ```html
 * <nys-label label="This is a basic nys-label"></nys-label>
 * ```
 *
 * @example Required
 * ```html
 * <nys-label label="This form is required" flag="required"></nys-label>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-label label="This form is required" flag="optional"></nys-label>
 * ```
 *
 * @example Description
 * ```html
 * <nys-label label="Label Text" description="Description text"></nys-label>
 * ```
 *
 * @example Description Slot
 * ```html
 * <nys-label label="Label Text">
 *   <p slot="description">Rich text description passed in <strong>HERE</strong></p>
 * </nys-label>
 * ```
 *
 * @example With Tooltip
 * ```html
 * <nys-label id="label-id" label="This label has a tooltip"></nys-label>
 * <nys-tooltip for="label-id" text="Tooltip text in here"></nys-tooltip>
 * ```
 *
 * @slot description - Custom HTML description content below the label.
 *
 * @fires {Event} nys-label-click - Fired when the label is clicked. Bubbles and composed. Listened for by form components (for example nys-fileinput and nys-toggle) that need label-activation behavior.
 */
export class NysLabel extends LitElement {
  static styles = unsafeCSS(styles);

  /** The ID of the label. */
  @property({ type: String, reflect: true }) id = "";

  /** Label text displayed above the form field. */
  @property({ type: String }) label = "";

  /** Helper text displayed below the label. */
  @property({ type: String }) description = "";

  /** Flag type: `required` shows asterisk, `optional` shows "(Optional)". */
  @property({ type: String }) flag = "";

  /** Adjusts colors for dark backgrounds. */
  @property({ type: Boolean, reflect: true }) inverted = false;
  /** Tooltip text shown on hover/focus of info icon next to label. */
  @property({ type: String }) tooltip = "";

  // Expose the (shadow-encapsulated) label text as the host's own accessible name so
  // references to <nys-label> resolve reliably across engines, instead of relying on
  // each browser flattening nested-shadow text. Guarded for SSR.
  private _labelInternals: ElementInternals | null =
    typeof this.attachInternals === "function" ? this.attachInternals() : null;

  private get _hasDescription() {
    // This accounts for both description prop or slotted content.
    const slot = this.querySelector('[slot="description"]');
    return !!this.description || !!slot;
  }

  connectedCallback() {
    super.connectedCallback();
    if (!this.id) {
      this.id = `nys-label-${Date.now()}-${labelIdCounter++}`;
    }
  }

  updated() {
    if (this._labelInternals) {
      this._labelInternals.ariaLabel = this.label || null;
    }
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  /**
   * While most components don't need to listen for this event.
   * Special components like "nys-fileinput" and "nys-toggle" need to listen for label to execute their specific functionalities.
   */
  private _dispatchLabelClick() {
    this.dispatchEvent(
      new CustomEvent("nys-label-click", { bubbles: true, composed: true }),
    );
  }

  render() {
    return html`
      <div class="nys-label ${this.inverted ? "invert" : ""}">
        <div class="nys-label__tooltip-wrapper">
          <label class="nys-label__label" @click=${this._dispatchLabelClick}
            >${this.label}
            ${this.flag === "required"
              ? html`<div class="nys-label__required" aria-hidden="true">
                  *
                </div>`
              : ""}
            ${this.flag === "optional"
              ? html`<div class="nys-label__optional">(Optional)</div>`
              : ""}</label
          >
          ${this.tooltip
            ? html`<nys-tooltip
                  text="${this.tooltip}"
                  position="top"
                  focusable
                  ?inverted=${this.inverted}
                  for="tooltip-icon-${this.id}"
                >
                </nys-tooltip>
                <nys-icon
                  id="tooltip-icon-${this.id}"
                  name="info"
                  size="3xl"
                ></nys-icon> `
            : ""}
        </div>
        ${this._hasDescription
          ? html`<p
              class="nys-label__description"
              @click=${this._dispatchLabelClick}
            >
              <slot name="description">${this.description}</slot>
            </p>`
          : ""}
      </div>
    `;
  }
}

if (!customElements.get("nys-label")) {
  customElements.define("nys-label", NysLabel);
}
