import { html, unsafeCSS } from "lit";
import { property, state } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import { NysElement } from "@nysds/internals";
// These elements are rendered inside this component's shadow DOM, so they must
// be registered whenever nys-alert is used. Importing them here (intentional
// side effect) guarantees the type icon and dismiss button always upgrade —
// the dismiss button's accessible name lands on nys-button's real inner
// <button>, which only exists once nys-button renders.
import "@nysds/nys-icon";
import "@nysds/nys-button";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-alert.scss?inline";

/** Detail payload for the `nys-close` event fired by `nys-alert`. */
export interface NysAlertCloseDetail {
  id: string;
  type: "base" | "info" | "success" | "warning" | "danger" | "emergency";
  label: string;
}

/** The `nys-close` event fired by `nys-alert`. */
export type NysAlertCloseEvent = CustomEvent<NysAlertCloseDetail>;

/**
 * Displays contextual feedback messages with semantic styling. Uses ARIA live regions for screen reader announcements.
 *
 * Use `info` for neutral information, `success` for confirmations, `warning` for caution, `danger` for errors,
 * and `emergency` for critical system-wide alerts. Set `dismissible` to let users close the alert.
 *
 * @summary Alert for contextual feedback with semantic types and live region support.
 * @element nys-alert
 *
 * @slot - Default slot for custom body content. Overrides `text` prop when provided.
 * 
 * @cssprop [--nys-alert-color] - Text color of heading and description
 * @cssprop [--nys-alert-color-link] - Text color of action links
 * @cssprop [--nys-alert-color--link--hover] - Text color of action links when hovered
 * @cssprop [--nys-alert-color--link--active] - Text color of action links when active
 * @cssprop [--nys-alert-border-color] - Color of border accent color
 * @cssprop [--nys-alert-background-color] - Background color of component
 *
 * @fires {NysAlertCloseEvent} nys-close - Fired when alert is dismissed. Detail: `{id, type, label}`.
 *
 * @usage
 * - Communicate important, time-sensitive information to users in a visually prominent way.
 * - Use for messages such as success notifications, danger alerts, warnings, or informational updates.
 * - Use for dismissible or temporary alerts when the message is not critical to user workflow.
 * - Use the appropriate theme (e.g., info, success, warning, or danger) to match the intent of the alert.
 * - Use the dismissible property for non-critical alerts.
 * - Keep the alert content concise and focused on the message.
 * - Limit alerts to one per page.
 * - Use success type to confirm a positive system status to users such as saving a form.
 * - Use danger type to display system status error messages.
 * - Only use emergency for real emergencies (e.g., missing person, severe weather). Remember to swap icon if a more relevant one exists.
 * - Don't use alerts for information that is not time-sensitive or critical; consider using an inline message instead.
 * - Don't use alerts for repetitive or non-actionable content that could frustrate users.
 * - Don't remove the left icon, it is required for accessibility.
 * - Don't use alerts to highlight actions that should be clear in the UI itself.
 * - Don't use error messages to communicate form field validation issues; use field error states instead.
 * - Don't include more than two link actions in an alert.
 * - Don't overuse alerts for low-priority info. This can desensitize users.
 * - Don't use alerts as toasts. Place them at the top of the page content.
 * - Don't add any shadows to alerts.
 *
 * @example Basic
 * ```html
 * <nys-alert heading="This is a heading"></nys-alert>
 * ```
 *
 * @example Text
 * ```html
 * <nys-alert
 *  heading="This is a heading"
 *  text="This is additional information passed in through the text property"
 * ></nys-alert>
 * ```
 *
 * @example Rich Text
 * ```html
 * <nys-alert heading="Rich Text">
 *  <p>This is a custom alert with <strong>HTML content</strong> passed in through the slot.</p>
 *  <a href="https://www.ny.gov/" target="_blank">Learn more about our accessibility services</a>
 * </nys-alert>
 * ```
 *
 * @example Info Type
 * ```html
 * <nys-alert type="info" heading="Info alert type"></nys-alert>
 * ```
 *
 * @example Success Type
 * ```html
 * <nys-alert type="success" heading="Success alert type"></nys-alert>
 * ```
 *
 * @example Warning Type
 * ```html
 * <nys-alert type="warning" heading="Warning alert type"></nys-alert>
 * ```
 *
 * @example Danger Type
 * ```html
 * <nys-alert type="danger" heading="Danger alert type"></nys-alert>
 * ```
 *
 * @example Emergency Type
 * ```html
 * <nys-alert type="emergency" heading="Emergency alert type"></nys-alert>
 * ```
 *
 * @example Dismissible
 * ```html
 * <nys-alert heading="This alert is dismisable" text="Close it by clicking on the X in the corner." dismissible>
 * </nys-alert>
 * ```
 *
 * @example Duration
 * ```html
 * <nys-alert heading="Disappearing alert" text="This alert will disappear after 3 seconds." duration="3000"></nys-alert>
 * ```
 *
 * @render Duration
 * ```html
 * <nys-button
 *  class="nys-margin-b-100"
 *  label="Show alert"
 *  onclick="document.body.appendChild(Object.assign(document.createElement('nys-alert'), {heading: 'Disappearing alert', text: 'This alert will disappear after 3 seconds.', duration: 3000}))"
 * ></nys-button>
 * ```
 *
 * @example Custom Icon
 * ```html
 * <nys-alert
 *   type="emergency"
 *   heading="Winter storm warning: Dec 10th, 2024."
 *   text="A major snowfall is expected across the state of New York for the weekend of Dec 7th. Stay home if possible and use extreme caution when driving."
 *   icon="ac_unit">
 * </nys-alert>
 *```

 * @example Action Links
 * ```html
 * <nys-alert
 *  heading="Alert with links"
 *  primaryLabel="{primaryAction}"
 *  secondaryLabel="{secondaryAction}"
 *  primaryAction="https://www.ny.gov/"
 *  secondaryAction="https://www.ny.gov/"
 * ></nys-alert>
 *```
 */

export class NysAlert extends NysElement {
  static styles = unsafeCSS(styles);

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Bold heading text displayed at the top of the alert. */
  @property({ type: String }) heading = "";

  /** Custom icon name. Defaults to type-appropriate icon if not set. */
  @property({ type: String }) icon = "";

  /** Shows close button allowing users to dismiss the alert. */
  @property({ type: Boolean, reflect: true }) dismissible = false;

  /** Auto-dismiss after specified milliseconds. Set to 0 to disable. */
  @property({ type: Number, reflect: true }) duration = 0;

  /** Body text content. Ignored if slot content is provided. */
  @property({ type: String }) text = "";

  /** URL for the primary action link. */
  @property({ type: String }) primaryAction = "";

  /** URL for the secondary action link. */
  @property({ type: String }) secondaryAction = "";

  /** Label text for primary action link. */
  @property({ type: String }) primaryLabel = "Learn more";

  /** Label text for secondary action link. */
  @property({ type: String }) secondaryLabel = "Dismiss";

  /**
   * Semantic alert type affecting color and ARIA role. `warning`/`danger`/`emergency` use
   * `role="alert"` (assertive live region); `base`/`info`/`success` use `role="status"` (polite).
   * @default "base"
   */
  @property({ type: String, reflect: true }) type:
    | "base"
    | "info"
    | "success"
    | "warning"
    | "danger"
    | "emergency" = "base";

  @state() private _alertClosed = false;
  @state() private _slotHasContent = true;

  /**
   * Returns the ARIA role and aria-live setting for the alert's live region based on type.
   * - `warning`/`danger`/`emergency` => role="alert", aria-live="assertive" (urgent, interrupts)
   * - `base`/`info`/`success` => role="status", aria-live="polite" (waits its turn)
   *
   * `aria-live` is set explicitly alongside `role` (rather than relying on the role's implicit
   * live-region semantics) for more consistent behavior across browser/AT combinations.
   */
  get ariaAttributes(): {
    role: "alert" | "status";
    ariaLive: "polite" | "assertive";
  } {
    const isUrgent =
      this.type === "warning" ||
      this.type === "danger" ||
      this.type === "emergency";

    return {
      role: isUrgent ? "alert" : "status",
      ariaLive: isUrgent ? "assertive" : "polite",
    };
  }

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   */

  private _timeoutId: any = null;

  connectedCallback() {
    // super.connectedCallback() (NysElement) assigns an id when one
    // is not provided. The live-region role/aria-live/aria-atomic and the
    // announced content they wrap must live on the SAME element
    // (.nys-alert__texts) so the accessible name/role pairing is never split
    // across nested elements (see nysds#1092). The dismiss button lives
    // outside .nys-alert__texts as a sibling so it is never read as part of
    // the announced content. This component intentionally keeps
    // defaultRole = null and does not move role to the host.
    super.connectedCallback();

    // For alerts that have durations, we set a timer to close them.
    if (this.duration > 0) {
      this._timeoutId = setTimeout(() => {
        this._closeAlert();
      }, this.duration);
    }
  }

  disconnectedCallback() {
    if (this._timeoutId) {
      clearTimeout(this._timeoutId);
    }
    super.disconnectedCallback();
  }

  firstUpdated() {
    this._checkSlotContent();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */
  private _resolveIconName() {
    return this.icon || this._checkAltNaming();
  }

  private _checkAltNaming() {
    // map 'success' to 'check_circle'
    return this.type === "success"
      ? "check_circle"
      : this.type === "base"
        ? "info"
        : this.type === "danger"
          ? "error"
          : this.type === "emergency"
            ? "emergency_home"
            : this.type;
  }

  private _closeAlert() {
    this._alertClosed = true;
    /* Dispatch a custom event for the close action:
     * allows bubbling up so if developers wish to implement a local save to remember closed alerts.
     */
    this.dispatchEvent(
      new CustomEvent("nys-close", {
        detail: { id: this.id, type: this.type, label: this.heading },
        bubbles: true,
        composed: true,
      }),
    );
  }

  /**
   * Checks whether the default slot has content.
   * Updates `_slotHasContent` accordingly.
   */
  private async _checkSlotContent() {
    const slot = this.shadowRoot?.querySelector<HTMLSlotElement>("slot");
    if (slot) {
      // Check if slot has assigned nodes with content (elements or non-empty text nodes)
      const assignedNodes = slot
        .assignedNodes({ flatten: true })
        .filter(
          (node) =>
            node.nodeType === Node.ELEMENT_NODE ||
            (node.nodeType === Node.TEXT_NODE && node.textContent?.trim()),
        );

      await Promise.resolve();
      this._slotHasContent = assignedNodes.length > 0;
    } else {
      await Promise.resolve();
      this._slotHasContent = false; // No slot found
    }
  }

  render() {
    const { role, ariaLive } = this.ariaAttributes;

    return html`
      ${!this._alertClosed
        ? html` <div
            class="nys-alert__container ${this._slotHasContent ||
            this.text?.trim().length > 0 ||
            this.primaryAction ||
            this.secondaryAction
              ? ""
              : "nys-alert--centered"}"
          >
            <div part="nys-alert__icon" class="nys-alert__icon">
              <nys-icon
                name="${this._resolveIconName()}"
                size="3xl"
                label="${this.type} icon"
              ></nys-icon>
            </div>
            <div
              class="nys-alert__texts"
              role=${role}
              aria-live=${ariaLive}
              aria-atomic="true"
            >
              ${this.heading?.trim()
                ? html`<p class="nys-alert__header">${this.heading}</p>`
                : ""}
              ${this._slotHasContent
                ? html`<slot></slot>`
                : this.text?.trim().length > 0
                  ? html`<p class="nys-alert__text">${this.text}</p>`
                  : ""}
              ${this.primaryAction || this.secondaryAction
                ? html`<div class="nys-alert__actions">
                    ${this.primaryAction
                      ? html`<nys-button
                          variant="text"
                          target="_blank"
                          href=${this.primaryAction}
                          label=${this.primaryLabel}
                          ?inverted=${this.type === "emergency"}
                          id="primary-action"
                        ></nys-button>`
                      : ""}
                    ${this.secondaryAction
                      ? html`<nys-button
                          variant="text"
                          target="_blank"
                          href=${this.secondaryAction}
                          label=${this.secondaryLabel}
                          ?inverted=${this.type === "emergency"}
                          id="secondary-action"
                        ></nys-button>`
                      : ""}
                  </div> `
                : ""}
            </div>
            ${this.dismissible
              ? html` <nys-button
                  id="dismiss-btn"
                  variant="ghost"
                  circle
                  icon="close"
                  size="sm"
                  ?inverted=${this.type === "emergency"}
                  label="${this.heading}, alert, Close"
                  @nys-click=${this._closeAlert}
                  style=${ifDefined(
                    this.type === "emergency"
                      ? "--_nys-button-outline-color: var(--nys-color-ink-reverse, var(--nys-color-white, #fff));"
                      : undefined,
                  )}
                ></nys-button>`
              : ""}
          </div>`
        : ""}
    `;
  }
}

if (!customElements.get("nys-alert")) {
  customElements.define("nys-alert", NysAlert);
}
