import { LitElement, html, unsafeCSS } from "lit";
import { property } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import {
  NysFormControlElement,
  dispatchNysEvent,
  dispatchNysFocusBlur,
} from "@nysds/internals";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-textarea is used. Importing them here
// (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-textarea.scss?inline";

/** Detail payload for the `nys-input` event. */
export interface NysTextareaInputDetail {
  id: string;
  name: string;
  value: string;
}

/** The `nys-input` event, fired on each keystroke. */
export type NysTextareaInputEvent = CustomEvent<NysTextareaInputDetail>;

/** Detail payload for the `nys-change` event. */
export interface NysTextareaChangeDetail {
  id: string;
  name: string;
  value: string;
}

/** The `nys-change` event, fired when the value is committed. */
export type NysTextareaChangeEvent = CustomEvent<NysTextareaChangeDetail>;

/** Detail payload for the `nys-select` event. */
export interface NysTextareaSelectDetail {
  id: string;
  value: string;
}

/** The `nys-select` event, fired when the user selects text. */
export type NysTextareaSelectEvent = CustomEvent<NysTextareaSelectDetail>;

/** Detail payload for the `nys-selectionchange` event. */
export interface NysTextareaSelectionchangeDetail {
  id: string;
  value: string;
}

/** The `nys-selectionchange` event, fired when the text selection changes. */
export type NysTextareaSelectionchangeEvent =
  CustomEvent<NysTextareaSelectionchangeDetail>;

/**
 * A multi-line text input for collecting longer responses like comments, descriptions, or feedback.
 * Form-associated with validation support via ElementInternals.
 *
 * Use for detailed responses needing multiple lines. For single-line input, use `nys-textinput`.
 * For predefined options, use `nys-select`, `nys-radiobutton`, or `nys-checkbox`.
 *
 * @summary Multi-line text input for comments, descriptions, and feedback.
 * @element nys-textarea
 *
 * @slot description - Custom HTML description content below the label.
 *
 * @formControl value nys-change nys-input
 *
 * @fires {NysTextareaInputEvent} nys-input - Fired on each input. Detail: `{id, name, value}`.
 * @fires {NysTextareaChangeEvent} nys-change - Fired when the value is committed (native `change`). Detail: `{id, name, value}`.
 * @fires {Event} nys-focus - Fired when the textarea gains focus.
 * @fires {Event} nys-blur - Fired when the textarea loses focus. Triggers validation.
 * @fires {NysTextareaSelectEvent} nys-select - Fired when the user selects text. Detail: `{id, value}`.
 * @fires {NysTextareaSelectionchangeEvent} nys-selectionchange - Fired when the text selection changes. Detail: `{id, value}`.
 *
 * @usage
 * - Use to collect multiple lines of open-ended text input (e.g., comments, descriptions, feedback).
 * - Don't use for short or single-line input. Use `<nys-textinput>` instead.
 * - Don't use when input should be selected from predefined options. Use `<nys-select>`, `<nys-radiobutton>`, or `<nys-checkbox>` instead.
 *
 * @example Basic
 * ```html
 * <nys-textarea label="Comments"></nys-textarea>
 * ```
 *
 * @example Disabled
 * ```html
 * <nys-textarea label="Comments" disabled></nys-textarea>
 * ```
 *
 * @example Readonly
 * ```html
 * <nys-textarea label="Comments" readonly value="You can see me but not edit me"></nys-textarea>
 * ```
 *
 * @example Required
 * ```html
 * <nys-textarea label="Describe the incident" required></nys-textarea>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-textarea label="Comments" optional></nys-textarea>
 * ```
 *
 * @example Max length
 * ```html
 * <nys-textarea label="Comments" maxlength="100"></nys-textarea>
 * ```
 *
 * @example Width Small
 * ```html
 * <nys-textarea label="Comments" width="sm"></nys-textarea>
 * ```
 *
 * @example Width Medium
 * ```html
 * <nys-textarea label="Comments" width="md"></nys-textarea>
 * ```
 *
 * @example Width Large
 * ```html
 * <nys-textarea label="Comments" width="lg"></nys-textarea>
 * ```
 *
 * @example Description
 * ```html
 * <nys-textarea label="Describe the incident" description="Please provide details"></nys-textarea>
 * ```
 *
 * @example Description Slot
 * ```html
 * <nys-textarea label="Describe the incident">
 *  <div slot="description">Please provide details</div>
 * </nys-textarea>
 * ```
 */

export class NysTextarea extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Name for form submission. */
  @property({ type: String, reflect: true }) name = "";

  /** Visible label text. Required for accessibility. */
  @property({ type: String }) label = "";

  /** Helper text below label. Use slot for custom HTML. */
  @property({ type: String }) description = "";

  /** Placeholder text. Don't use as label replacement. */
  @property({ type: String }) placeholder = "";

  /** Current textarea value. */
  @property({ type: String }) value = "";

  /** Prevents interaction. */
  @property({ type: Boolean, reflect: true }) disabled = false;

  /** Makes textarea readonly but focusable. */
  @property({ type: Boolean, reflect: true }) readonly = false;

  /** Marks as required. Shows "Required" flag and validates on blur. */
  @property({ type: Boolean, reflect: true }) required = false;

  /** Shows "Optional" flag. Use when most fields are required. */
  @property({ type: Boolean, reflect: true }) optional = false;

  /** Tooltip text shown on hover/focus of info icon. */
  @property({ type: String }) tooltip = "";

  /** Adjusts colors for dark backgrounds. */
  @property({ type: Boolean, reflect: true }) inverted = false;

  /** Form `id` to associate with when textarea is outside form element. */
  @property({ type: String, reflect: true }) form: string | null = null;

  /** Maximum character length. */
  @property({ type: Number }) maxlength: number | null = null;

  /**
   * Textarea width: `sm` (88px), `md` (200px), `lg` (384px), `full` (100%, default).
   * @default "full"
   */
  @property({ type: String, reflect: true }) width:
    | "sm"
    | "md"
    | "lg"
    | "full" = "full";

  /**
   * Visible height in lines.
   * @default 4
   */
  @property({ type: Number }) rows = 4;

  /**
   * Resize behavior: `vertical` (default, user can resize height), `none` (fixed size).
   * @default "vertical"
   */
  @property({ type: String, reflect: true }) resize: "vertical" | "none" =
    "vertical";

  /** Shows error message when true. Set by validation or manually. */
  @property({ type: Boolean, reflect: true }) showError = false;

  /** Error message text. Shown only when `showError` is true. */
  @property({ type: String }) errorMessage = "";

  /** Accessible label used only when no visible `label` is provided. */
  @property({ type: String }) ariaLabel = "";

  private _hasUserInteracted = false; // need this flag for "eager mode"

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */

  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this.addEventListener("invalid", this._handleInvalid);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("invalid", this._handleInvalid);
  }

  firstUpdated() {
    // This ensures our element always participates in the form
    this._setValue();
  }

  willUpdate(changedProperties: Map<string | number | symbol, unknown>) {
    if (changedProperties.has("rows") && this.rows == null) {
      this.rows = 4;
    }
  }

  async updated(changedProperties: Map<string | number | symbol, unknown>) {
    await Promise.resolve();

    if (changedProperties.has("value")) {
      this._setValue();
    }
    if (
      changedProperties.has("readonly") ||
      changedProperties.has("required")
    ) {
      const input = this.shadowRoot?.querySelector("textarea");

      if (input) input.required = this.required && !this.readonly;

      // Re-sync ElementInternals, not just the shadow <textarea>: `required`
      // can arrive as a late property write (e.g. a framework wrapper
      // setting it post-hydration, after firstUpdated already ran
      // _setValue()/_manageRequire() once against the old value). Without
      // this, ElementInternals keeps reporting valid, the native `invalid`
      // event never fires on submit, and showError never flips even though
      // the field is genuinely required and empty.
      this._manageRequire();
    }
  }

  /**
   * Form Integration
   * --------------------------------------------------------------------------
   */

  private _setValue() {
    this.setFormValue(this.value);
    this._manageRequire();
  }

  private _manageRequire() {
    const textarea = this.shadowRoot?.querySelector("textarea");

    if (!textarea) return;

    const isInvalid = this.required && !this.value;

    if (isInvalid) {
      this.internalValidationMessage = "This field is required";
      this.setValidityFromState(
        { valueMissing: true },
        this.resolvedErrorMessage(),
        textarea,
      );
    } else {
      this.internalValidationMessage = "";
      this.clearValidity();
      this._hasUserInteracted = false; // Reset lazy validation when valid
    }
  }

  private _setValidityMessage(message: string = "") {
    const textarea = this.shadowRoot?.querySelector("textarea");
    if (!textarea) return;

    // Toggle the HTML <div> tag error message
    this.showError = !!message;
    // Store the component's own validation text; a consumer-supplied
    // errorMessage always wins via resolvedErrorMessage().
    this.internalValidationMessage = message;

    if (message) {
      this.setValidityFromState(
        { customError: true },
        this.resolvedErrorMessage(),
        textarea,
      );
    } else {
      this.clearValidity();
    }
  }

  private _validate() {
    const textarea = this.shadowRoot?.querySelector("textarea");
    if (!textarea) return;

    // Get the native validation state
    let message = textarea.validationMessage;

    this._setValidityMessage(message);
  }

  // This callback is automatically called when the parent form is reset.
  public formResetCallback() {
    this.value = "";

    const textarea = this.shadowRoot?.querySelector("textarea");
    if (textarea) {
      textarea.value = "";
      textarea.setAttribute("aria-invalid", "false");
    }

    // Reset validation UI. Clears only the component's own validation text;
    // a consumer-supplied errorMessage is never touched.
    this.showError = false;
    this.internalValidationMessage = "";
    this.clearValidity();

    // Re-render UI
    this.requestUpdate();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */

  // This helper function is called to perform the element's native validation.
  checkValidity(): boolean {
    const textarea = this.shadowRoot?.querySelector("textarea");
    return textarea ? textarea.checkValidity() : true;
  }

  private _handleInvalid(event: Event) {
    event.preventDefault();
    this._hasUserInteracted = true; // Start aggressive mode due to form submission
    this._validate();

    const textarea = this.shadowRoot?.querySelector("textarea");
    if (textarea) {
      // Focus only if this is the first invalid element (top-down approach)
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        // Find the first element in the form that is invalid
        const firstInvalidElement = elements.find(
          (element) =>
            typeof element.checkValidity === "function" &&
            !element.checkValidity(),
        );
        if (firstInvalidElement === this) {
          textarea.focus();
        }
      } else {
        // If not part of a form, simply focus.
        textarea.focus();
      }
    }
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  // Handle input event to check pattern validity
  private _handleInput(event: Event) {
    const textarea = event.target as HTMLInputElement;
    this.value = textarea.value;
    this.setFormValue(this.value);

    // Field is invalid after unfocused, validate aggressively on each input (e.g. Eager mode: a combination of aggressive and lazy.)
    if (this._hasUserInteracted) {
      this._validate();
    }

    dispatchNysEvent<NysTextareaInputDetail>(this, "nys-input", {
      id: this.id,
      name: this.name,
      value: this.value,
    });
  }

  // Handle native change (value committed on blur after edits)
  private _handleChange(event: Event) {
    const textarea = event.target as HTMLTextAreaElement;
    this.value = textarea.value;
    dispatchNysEvent<NysTextareaChangeDetail>(this, "nys-change", {
      id: this.id,
      name: this.name,
      value: this.value,
    });
  }

  // Handle focus event
  private _handleFocus() {
    dispatchNysFocusBlur(this, "focus");
  }

  // Handle blur event
  private _handleBlur() {
    if (!this._hasUserInteracted) {
      this._hasUserInteracted = true; // At initial unfocus: if textarea is invalid, start aggressive mode
    }

    this._validate();
    dispatchNysFocusBlur(this, "blur");
  }

  private _handleSelect(e: Event) {
    const textarea = e.target as HTMLTextAreaElement;
    this.value = textarea.value;
    dispatchNysEvent<NysTextareaSelectDetail>(this, "nys-select", {
      id: this.id,
      value: this.value,
    });
  }

  private _handleSelectionChange(e: Event) {
    const textarea = e.target as HTMLTextAreaElement;
    this.value = textarea.value;
    dispatchNysEvent<NysTextareaSelectionchangeDetail>(
      this,
      "nys-selectionchange",
      {
        id: this.id,
        value: this.value,
      },
    );
  }

  render() {
    return html`
      <div class="nys-textarea">
        <nys-label
          id="${this.id}--label"
          label=${this.label}
          description=${this.description}
          flag=${this.required && !this.readonly
            ? "required"
            : this.optional
              ? "optional"
              : ""}
          tooltip=${this.tooltip}
          ?inverted=${this.inverted}
        >
          <slot name="description" slot="description">${this.description}</slot>
        </nys-label>
        <textarea
          class="nys-textarea__textarea ${this.resize}"
          name=${this.name}
          id=${this.id}
          .value=${this.value}
          ?disabled=${this.disabled}
          ?required=${this.required && !this.readonly}
          ?readonly=${this.readonly}
          aria-disabled=${ifDefined(this.disabled ? "true" : undefined)}
          aria-required=${ifDefined(this.required ? "true" : undefined)}
          aria-labelledby=${ifDefined(
            this.label ? this.id + "--label" : undefined,
          )}
          aria-label=${ifDefined(
            !this.label && this.ariaLabel ? this.ariaLabel : undefined,
          )}
          aria-description=${ifDefined(this.description || undefined)}
          aria-invalid=${this.showError ? "true" : "false"}
          aria-errormessage=${this.id + "--error"}
          aria-describedby=${ifDefined(
            this.showError ? this.id + "--error" : undefined,
          )}
          placeholder=${ifDefined(
            this.placeholder ? this.placeholder : undefined,
          )}
          maxlength=${ifDefined(this.maxlength ?? undefined)}
          .rows=${this.rows}
          form=${ifDefined(this.form || undefined)}
          @input=${this._handleInput}
          @change=${this._handleChange}
          @focus="${this._handleFocus}"
          @blur="${this._handleBlur}"
          @select="${this._handleSelect}"
          @selectionchange="${this._handleSelectionChange}"
        ></textarea>
        <nys-errormessage
          id=${this.id + "--error"}
          ?showError=${this.showError}
          errorMessage=${this.resolvedErrorMessage()}
        ></nys-errormessage>
      </div>
    `;
  }
}

if (!customElements.get("nys-textarea")) {
  customElements.define("nys-textarea", NysTextarea);
}
